const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@62..125,400..900&family=IBM+Plex+Mono:wght@400;500&family=IBM+Plex+Sans:wght@400;450;600&display=swap');

.site {
  --sans: 'IBM Plex Sans', system-ui, sans-serif;
  --mono: 'IBM Plex Mono', ui-monospace, monospace;
  --wide: 'Archivo', 'Arial Narrow', system-ui, sans-serif;
  background: var(--void);
  color: var(--bone);
  font-family: var(--sans);
  min-height: 100vh;
  overflow-x: hidden;
}
.site *, .site *::before, .site *::after { box-sizing: border-box; }
.site h1, .site h2, .site h3 { margin: 0; }
.site p { margin: 0; }
.site a { color: inherit; text-decoration: none; }
.site ::selection { background: var(--flare); color: var(--on-flare); }

.site :focus-visible {
  outline: 2px solid var(--flare);
  outline-offset: 3px;
  border-radius: 2px;
}

.skip {
  position: absolute; left: -9999px; top: 10px; z-index: 200;
  background: var(--flare); color: var(--on-flare);
  padding: 12px 20px; font-family: var(--mono); font-size: 13px;
}
.skip:focus { left: 16px; }

.wrap { max-width: 1160px; margin: 0 auto; padding: 0 24px; }
.site section { scroll-margin-top: 72px; }

/* ---- rail: a thin instrument header, not a floating glass bar ---- */
.rail {
  position: sticky; top: 0; z-index: 100;
  background: var(--void);
  border-bottom: 1px solid transparent;
  transition: border-color .2s linear;
}
.rail.solid { border-bottom-color: var(--line); }
.rail-in {
  max-width: 1160px; margin: 0 auto; padding: 0 24px;
  height: 56px; display: flex; align-items: center; gap: 20px;
}
.sig {
  font-family: var(--wide); font-stretch: 112%; font-weight: 700;
  font-size: 15px; letter-spacing: .01em; white-space: nowrap;
}
.sig span { color: var(--flare); }
.rail-nav { display: none; gap: 22px; margin-left: auto; }
.rail-nav a {
  font-family: var(--mono); font-size: 12px; color: var(--dim);
  padding: 6px 0; border-bottom: 1px solid transparent; transition: color .15s, border-color .15s;
}
.rail-nav a:hover { color: var(--bone); border-bottom-color: var(--flare); }
.rail-end { display: flex; gap: 8px; margin-left: auto; align-items: center; }
.rail-nav ~ .rail-end { margin-left: 0; }
.ctl {
  font-family: var(--mono); font-size: 11px; letter-spacing: .06em;
  background: transparent; color: var(--dim);
  border: 1px solid var(--line); padding: 0 12px;
  min-height: 34px; cursor: pointer;
  transition: color .15s, border-color .15s;
}
.ctl:hover { color: var(--bone); border-color: var(--line-bold); }
.drawer { display: flex; flex-direction: column; border-top: 1px solid var(--line); background: var(--panel); }
.drawer[hidden] { display: none; }
.drawer a {
  font-family: var(--mono); font-size: 14px; padding: 16px 24px;
  border-bottom: 1px solid var(--line); min-height: 44px;
}

/* ---- motion: one gesture, used everywhere, nothing else ---- */
.rv { opacity: 0; transform: translateY(14px); transition: opacity .5s ease, transform .5s cubic-bezier(.2,.7,.3,1); }
.rv.in { opacity: 1; transform: none; }

/* ---- hero: the one loud moment ---- */
.hero { padding: 72px 0 0; }
.site .tick {
  font-family: var(--mono); font-size: 11px; letter-spacing: .08em;
  color: var(--dim); text-transform: uppercase;
}
.hero h1 {
  font-family: var(--wide); font-stretch: 125%; font-weight: 800;
  font-size: clamp(40px, 11vw, 116px);
  line-height: .92; letter-spacing: -.03em;
  margin: 18px 0 0; display: flex; flex-direction: column;
}
.hero h1 em { font-style: normal; color: var(--flare); }
.hero h1 .l1, .hero h1 .l2 { display: block; }
@media (prefers-reduced-motion: no-preference) {
  .hero h1 .l1, .hero h1 .l2 { animation: lift .7s cubic-bezier(.2,.7,.3,1) both; }
  .hero h1 .l2 { animation-delay: .1s; }
  @keyframes lift { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: none; } }
}
.hero-grid { display: grid; gap: 32px; margin-top: 36px; }
.site .lede { font-size: clamp(16px, 2.2vw, 19px); line-height: 1.6; color: var(--dim); max-width: 46ch; }
.hero-cta { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 28px; }
.btn {
  display: inline-flex; align-items: center; min-height: 46px; padding: 0 22px;
  background: var(--flare); color: var(--on-flare);
  font-weight: 600; font-size: 15px;
  border: 1px solid var(--flare); cursor: pointer;
  transition: transform .15s ease, opacity .15s ease;
}
.btn:hover { transform: translateY(-2px); }
.btn.ghost { background: transparent; color: var(--bone); border-color: var(--line-bold); }
.btn.ghost:hover { border-color: var(--flare); }
.portrait { position: relative; width: 190px; }
.portrait .shot { aspect-ratio: 1; }
.tick-r { display: block; margin-top: 8px; }

.spec {
  display: grid; grid-template-columns: 1fr; margin: 56px 0 0;
  column-gap: 32px;
  border-top: 1px solid var(--line);
}
.spec > div { padding: 16px 0; border-bottom: 1px solid var(--line); }
.spec dt { font-family: var(--mono); font-size: 11px; letter-spacing: .08em; text-transform: uppercase; color: var(--flare); }
.spec dd { margin: 6px 0 0; font-size: 15px; color: var(--bone); }

/* ---- work: full-width rows, alternating, big images ---- */
.work { padding: 88px 0; }
.sec-head { display: flex; flex-wrap: wrap; gap: 18px; align-items: end; justify-content: space-between; margin-bottom: 44px; }
.site h2 {
  font-family: var(--wide); font-stretch: 118%; font-weight: 800;
  font-size: clamp(28px, 5vw, 46px); line-height: 1; letter-spacing: -.02em;
}
.filters { display: flex; gap: 6px; flex-wrap: wrap; }
.chip {
  font-family: var(--mono); font-size: 12px; min-height: 36px; padding: 0 14px;
  background: transparent; color: var(--dim); border: 1px solid var(--line); cursor: pointer;
  transition: color .15s, border-color .15s, background .15s;
}
.chip:hover { color: var(--bone); }
.chip.on { background: var(--flare); border-color: var(--flare); color: var(--on-flare); }
.empty {
  border: 1px dashed var(--line-bold); padding: 40px 24px; text-align: center;
  color: var(--dim); font-family: var(--mono); font-size: 14px;
}
.rows { display: flex; flex-direction: column; gap: 0; }
.row-wrap { border-top: 1px solid var(--line); padding: 44px 0; }
.row-wrap:last-child { border-bottom: 1px solid var(--line); }
.row { display: grid; gap: 28px; }
.row-head { display: flex; align-items: center; gap: 14px; margin-bottom: 12px; }
.numeral {
  font-family: var(--wide); font-stretch: 125%; font-weight: 800;
  font-size: clamp(38px, 7vw, 64px); line-height: .8; color: var(--line-bold);
}
.status {
  font-family: var(--mono); font-size: 10px; letter-spacing: .1em;
  border: 1px solid var(--line-bold); color: var(--dim); padding: 4px 8px;
}
.status.live { color: var(--flare); border-color: var(--flare); }
.row-body h3 {
  font-family: var(--wide); font-stretch: 112%; font-weight: 700;
  font-size: clamp(22px, 3.4vw, 30px); line-height: 1.1; letter-spacing: -.01em;
}
.site .role { font-family: var(--mono); font-size: 12px; color: var(--dim); margin-top: 8px; }
.site .body { font-size: 16px; line-height: 1.65; color: var(--dim); margin-top: 16px; max-width: 62ch; }
.row-body .body { color: var(--bone); opacity: .82; }
.stack { display: flex; flex-wrap: wrap; gap: 0; list-style: none; padding: 0; margin: 20px 0 0; }
.stack li {
  font-family: var(--mono); font-size: 11px; color: var(--dim);
  padding: 4px 12px 4px 0; margin-right: 12px; border-right: 1px solid var(--line);
}
.stack li:last-child { border-right: 0; margin-right: 0; }
.row-links { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 22px; }
.link-btn {
  display: inline-flex; align-items: center; min-height: 40px; padding: 0 16px;
  font-family: var(--mono); font-size: 12px; color: var(--flare);
  border: 1px solid var(--flare); transition: background .15s, color .15s;
}
.link-btn:hover { background: var(--flare); color: var(--on-flare); }

/* ---- images: sized so game work is actually visible ---- */
.gallery { display: flex; flex-direction: column; gap: 10px; }
.shot {
  position: relative; aspect-ratio: 16 / 10; background: var(--panel);
  border: 1px solid var(--line); overflow: hidden;
}
.shot.shot-tall { aspect-ratio: 16 / 9; }
.shot img { width: 100%; height: 100%; object-fit: cover; display: block; }
.shot[data-state="pending"] img, .shot[data-state="failed"] img { opacity: 0; }
.shot-note {
  position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
  font-family: var(--mono); font-size: 11px; letter-spacing: .08em; color: var(--dim);
  text-transform: uppercase;
}
.gallery-strip { display: flex; gap: 8px; }
.thumb {
  width: 76px; height: 52px; padding: 0; cursor: pointer; background: var(--panel);
  border: 1px solid var(--line); opacity: .55; transition: opacity .15s, border-color .15s;
}
.thumb img { width: 100%; height: 100%; object-fit: cover; display: block; }
.thumb:hover { opacity: .85; }
.thumb.on { opacity: 1; border-color: var(--flare); }

/* ---- now ---- */
.now { padding: 0 0 88px; }
.now-row { display: grid; gap: 16px; border-top: 1px solid var(--line); padding-top: 28px; margin-top: 28px; }
.now-meta { display: flex; align-items: center; gap: 12px; }
.now h3 { font-family: var(--wide); font-stretch: 112%; font-weight: 700; font-size: 24px; }

/* ---- about: asymmetric, no cards ---- */
.about { padding: 88px 0; border-top: 1px solid var(--line); }
.about-grid { display: grid; gap: 40px; }
.site .statement {
  font-family: var(--wide); font-stretch: 112%; font-weight: 700;
  font-size: clamp(22px, 3.6vw, 34px); line-height: 1.15; letter-spacing: -.01em;
  border-left: 3px solid var(--flare); padding-left: 22px;
}

/* ---- toolkit: a spec sheet, not a card grid ---- */
.toolkit { padding: 0 0 88px; }
.sheet { margin: 32px 0 0; border-top: 1px solid var(--line); }
.sheet-row { display: grid; gap: 8px; padding: 20px 0; border-bottom: 1px solid var(--line); }
.sheet dt {
  font-family: var(--mono); font-size: 11px; letter-spacing: .08em;
  text-transform: uppercase; color: var(--flare);
}
.sheet dd { margin: 0; display: flex; flex-wrap: wrap; gap: 8px 20px; }
.sheet dd span { font-size: 16px; }

/* ---- resume ---- */
.resume { padding: 0 0 88px; }
.resume-in {
  display: flex; flex-wrap: wrap; gap: 24px; align-items: center; justify-content: space-between;
  border: 1px solid var(--line); padding: 32px 28px; background: var(--panel);
}

/* ---- contact: left aligned, no centered dark slab ---- */
.contact { padding: 72px 0 96px; border-top: 1px solid var(--line); }
.contact h2 { margin: 14px 0 0; max-width: 16ch; }
.contact .body { margin-top: 18px; }

footer { border-top: 1px solid var(--line); padding: 24px 0; }
.foot {
  display: flex; flex-wrap: wrap; gap: 12px; justify-content: space-between;
  font-family: var(--mono); font-size: 11px; color: var(--dim);
}
.foot a:hover { color: var(--flare); }

@media (max-width: 899px) {
  .chip, .ctl { min-height: 44px; }
  .thumb { width: 84px; height: 58px; }
}

@media (min-width: 680px) {
  .spec { grid-template-columns: repeat(2, 1fr); column-gap: 32px; }
  .sheet-row { grid-template-columns: 200px 1fr; gap: 24px; align-items: baseline; }
}

@media (min-width: 900px) {
  .rail-nav { display: flex; }
  .menu-btn { display: none; }
  .drawer { display: none !important; }
  .hero { padding: 104px 0 0; }
  .hero-grid { grid-template-columns: 1fr 190px; gap: 56px; align-items: start; }
  .spec { grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); }
  .row { grid-template-columns: 1.1fr 1fr; gap: 52px; align-items: center; }
  .row.flip .row-media { order: 2; }
  .row.feature { grid-template-columns: 1fr; gap: 36px; }
  .row.textonly { grid-template-columns: 1fr; max-width: 78ch; }
  .row.feature .row-body { display: grid; grid-template-columns: 1fr 1fr; gap: 0 52px; align-items: start; }
  .row.feature .row-head, .row.feature h3, .row.feature .role { grid-column: 1; }
  .row.feature .body { grid-column: 2; grid-row: 1 / span 3; margin-top: 0; }
  .about-grid { grid-template-columns: 1fr 1fr; gap: 72px; align-items: start; }
}

@media (prefers-reduced-motion: reduce) {
  .site *, .site *::before, .site *::after {
    animation-duration: .001ms !important;
    transition-duration: .001ms !important;
  }
  .rv { opacity: 1; transform: none; }
}
`;
